const now = Date.now();
const vids = $('Lire vidéos').first().json.data || [];
const src = Object.fromEntries(($('Lire sources').first().json.data || []).map(s => [s.channel_id, s]));
const pubs = $('Lire publications').first().json.data || [];
const segsOf = p => { try { const j = JSON.parse(p.segments || '[]'); return Array.isArray(j) ? j : (j.segments || []); } catch (e) { return []; } };
const deja = new Set(pubs.filter(p => p.type === 'zapping').flatMap(p => segsOf(p).map(x => x.video_id)));
let c = vids.filter(v => {
  const s = src[v.channel_id];
  return s && s.statut === 'usable' && v.publiee_le && now - Date.parse(v.publiee_le) < 30 * 3600e3
    && !['pas_interessant', 'source_ignoree'].includes(v.decision) && !deja.has(v.video_id) && (v.duree_s || 0) >= 20;
}).map(v => ({ ...v, prio: (v.score || 0) + (v.decision === 'interessant' ? 3 : 0) }));
c.sort((a, b) => b.prio - a.prio);
const parSrc = {}; const out = [];
for (const v of c) { parSrc[v.channel_id] = (parSrc[v.channel_id] || 0) + 1; if (parSrc[v.channel_id] > 3) continue; out.push(v); if (out.length >= 18) break; }
if (out.length < 6) throw new Error(`Pas assez de matière pour le zapping (${out.length} vidéos utilisables sur 30 h)`);
return out.map(v => ({ json: { video_id: v.video_id, titre: v.titre, source_nom: v.source_nom, channel_id: v.channel_id,
  categorie: src[v.channel_id].categorie, score: v.score, decision: v.decision || '', angle: v.angle || '', duree_s: v.duree_s,
  extrait_debut: v.extrait_debut, extrait_fin: v.extrait_fin, personnes: v.personnes || '', camp: v.camp || '', theme: v.theme || '', type_moment: v.type_moment || '' } }));

const cands = $('Choisir les candidats').all();
const lecons = (($('Lire leçons').first().json.data || [])[0] || {}).texte || '';
const out = [];
$input.all().forEach((it, i) => {
  const c = cands[i].json; const ph = it.json.phrases || [];
  if (!ph.length) return;
  let txt = ph.map(p => `[${p.start}-${p.end}] ${p.texte}`).join('\n');
  if (txt.length > 30000) txt = txt.slice(0, 30000) + '\n[…transcription tronquée]';
  const tv = c.categorie === 'tv_radio' || c.categorie === 'emission';
  const hint = c.extrait_debut != null ? `\nIndice : Louis a déjà validé le passage ${c.extrait_debut}-${c.extrait_fin} s pour un Short.` : '';
  const system = `Tu es monteur pour « L'Extrait politique », zapping quotidien de la politique française sur YouTube.
Dans la transcription horodatée ci-dessous, choisis LE meilleur moment pour le zapping du jour :
- entre 20 et ${tv ? 45 : 60} secondes, compréhensible seul, qui commence au début d'une phrase et finit à la fin d'une phrase (utilise les horodatages) ;
- privilégie clash, punchline, contradiction, aveu, chiffre choc ;
- donne un titre de chapitre (≤ 6 mots, factuel, sans insulte) et une phrase de contexte neutre (≤ 15 mots) ;
- évalue honnêtement : interet (0-10) et risque_demonetisation (0-10 : violence, sexualité, accusations non établies, grossièretés, tragédie).
Règles apprises à respecter :\n${lecons}
Réponds UNIQUEMENT en JSON : {"start":0,"end":0,"titre":"...","contexte":"...","interet":0,"risque_demonetisation":0,"raison":"..."}`;
  out.push({ json: { cand: c, body: { model: 'claude-sonnet-4-5', max_tokens: 600, system,
    messages: [{ role: 'user', content: `Vidéo : ${c.titre}\nSource : ${c.source_nom} (${c.categorie})\nDécision de Louis : ${['interessant','pas_interessant'].includes(c.decision) ? c.decision : (c.decision === 'choix_ia' ? 'aucune (choisi par l\'IA)' : 'aucune')}${hint}\n\nTranscription :\n${txt}` }] } } });
});
if (out.length < 5) throw new Error(`Seulement ${out.length} vidéos transcrites, zapping annulé`);
return out;

const preps = $('Préparer les moments').all();
const res = [];
$input.all().forEach((it, i) => {
  const c = preps[i].json.cand;
  const txt = (it.json.content || []).map(x => x.text || '').join('');
  try {
    const m = JSON.parse(txt.slice(txt.indexOf('{'), txt.lastIndexOf('}') + 1));
    const d = m.end - m.start;
    if (!(d >= 12 && d <= 75)) return;
    res.push({ id: res.length, video_id: c.video_id, source: c.source_nom, categorie: c.categorie, decision_louis: c.decision,
      score_veille: c.score, titre_video: c.titre, personnes: c.personnes, camp: c.camp, theme: c.theme, type_moment: c.type_moment, start: +m.start, end: +m.end, duree: Math.round(d), titre: m.titre, contexte: m.contexte,
      interet: m.interet, risque_demonetisation: m.risque_demonetisation, raison: m.raison });
  } catch (e) {}
});
const lecons = (($('Lire leçons').first().json.data || [])[0] || {}).texte || '';
const d = new Date();
const dateLabel = d.toLocaleDateString('fr-FR', { day: 'numeric', month: 'long', timeZone: 'Europe/Paris' });
const system = `Tu es le rédacteur en chef de « L'Extrait politique », le zapping quotidien de la politique française (YouTube, 19h).
Objectif business : 3 000 €/mois le plus vite possible, sans JAMAIS prendre de strike ni être démonétisé.
Construis le conducteur du zapping du ${dateLabel} à partir des moments proposés :
- durée totale des extraits entre 400 et 500 secondes (avec la voix off, l'intro et l'outro, la vidéo finale doit faire 8 à 10 minutes) ;
- 9 à 14 extraits ; ouvre sur le moment le plus fort et le moins risqué (rétention des 30 premières secondes) ; enchaîne par thèmes ; garde un moment fort pour la fin ;
- écarte tout moment avec risque_demonetisation ≥ 6 ; au plus 2 extraits par chaîne TV ; équilibre les camps politiques ;
- tu peux raccourcir un extrait (ajuste start/end) mais jamais l'allonger ;
- applique strictement les leçons apprises ci-dessous, et consacre environ 20 % du zapping à UNE hypothèse nouvelle que tu formules (pour apprendre) ;
- VOIX OFF (c'est notre valeur ajoutée éditoriale, indispensable pour la monétisation) : écris un texte lu par une voix de synthèse
  · voix_intro : 2-3 phrases (≈ 15 s) qui commencent par « Bonsoir, voici L'Extrait politique du ${dateLabel}. » puis annoncent les sujets forts du jour ;
  · pour chaque segment, voix : 1-2 phrases (≈ 6 à 12 s, 30 mots max) AVANT l'extrait : qui parle (nom + fonction), où, dans quel contexte et pourquoi c'est important ; ton de présentateur de JT, neutre, factuel, jamais d'opinion ni de moquerie, même traitement pour tous les camps ;
  · n'affirme que ce qui figure dans les éléments fournis (titre, contexte, transcription) : aucun fait inventé, aucun chiffre non sourcé, aucune accusation ;
  · voix_outro : 1-2 phrases (≈ 8 s) : rendez-vous demain à 19h et invitation à s'abonner ;
  · écris pour l'oral : phrases courtes, pas d'abréviations ni de sigles obscurs (écris « Rassemblement national » la première fois), nombres en toutes lettres si courts ;
- TITRE YouTube (≤ 80 caractères) écrit pour faire CLIQUER, à la manière des grosses chaînes d'actu : émotion forte, tension, curiosité (ex. « Bardella EXPLOSE face à… », « Ce qu'il a dit à l'Assemblée choque tout le monde », « Le clash qui fait trembler le gouvernement ») ; nomme la personnalité la plus connue ; 1 ou 2 mots en MAJUSCULES max ; pas d'emoji ; JAMAIS mensonger : le titre doit correspondre à ce qu'on voit réellement (YouTube sanctionne le clickbait trompeur), aucune accusation, aucune insulte ;
- accroche ≤ 60 caractères pour l'intro ; description de 2-3 phrases ; 8 à 12 tags ;
- MINIATURE : vedette = id du segment dont la personne apparaîtra sur la miniature (la plus connue, au moment le plus intense) ; miniature_texte = 2 à 4 mots CHOC en français, très lisibles, différents du titre (ex. « IL CRAQUE EN DIRECT », « HUMILIÉ À L'ASSEMBLÉE », « LA PHRASE DE TROP »), fidèle à l'extrait ; decor_prompt = en anglais, description d'un décor de fond dramatique et symbolique lié au sujet, SANS personne ni texte (ex. « French National Assembly hemicycle under a red stormy sky, smoke, red alarm light », « torn French flag in front of a burning ballot box »), jamais de sang, d'armes ni de violence explicite ;
LEÇONS APPRISES :\n${lecons}
Réponds UNIQUEMENT en JSON :
{"titre":"...","accroche":"...","description":"...","tags":["..."],"hypothese":"...","voix_intro":"...","voix_outro":"...","vedette":0,"miniature_texte":"...","decor_prompt":"...","segments":[{"id":0,"start":0,"end":0,"titre":"...","contexte":"...","voix":"..."}]}`;
return [{ json: { moments: res, dateLabel, body: { model: 'claude-sonnet-4-5', max_tokens: 6000, system, messages: [{ role: 'user', content: JSON.stringify(res) }] } } }];

const prev = $('Rédaction').first().json;
const byId = Object.fromEntries(prev.moments.map(m => [m.id, m]));
const txt = ($input.first().json.content || []).map(x => x.text || '').join('');
const r = JSON.parse(txt.slice(txt.indexOf('{'), txt.lastIndexOf('}') + 1));
const segs = [];
for (const s of r.segments || []) {
  const m = byId[s.id]; if (!m) continue;
  let a = Math.max(m.start, +s.start || m.start), b = Math.min(m.end, +s.end || m.end);
  if (b - a < 10) { a = m.start; b = m.end; }
  segs.push({ video_id: m.video_id, start: a, end: b, id_moment: s.id, titre: s.titre || m.titre, contexte: s.contexte || m.contexte, voix: String(s.voix || '').slice(0, 400), source: m.source, categorie: m.categorie, personnes: m.personnes, camp: m.camp, theme: m.theme, type_moment: m.type_moment });
}
if (segs.length < 5) throw new Error('Conducteur trop court : ' + segs.length + ' extraits');
const total = segs.reduce((t, s) => t + (s.end - s.start), 0);
const ymd = new Date().toLocaleDateString('sv-SE', { timeZone: 'Europe/Paris' });
const nom = 'zap_' + ymd.replace(/-/g, '');
// heure de publication : 19h Paris aujourd'hui (ou tout de suite si déjà passé)
const offs = new Date().toLocaleString('en-US', { timeZone: 'Europe/Paris', timeZoneName: 'shortOffset' }).match(/GMT([+-]\d+)/);
const h = offs ? parseInt(offs[1]) : 2;
let pub = new Date(`${ymd}T19:00:00${h >= 0 ? '+' : '-'}${String(Math.abs(h)).padStart(2, '0')}:00`);
if (pub.getTime() < Date.now() + 60e3) pub = new Date(Date.now() + 60e3);
return [{ json: { nom, ymd, dateLabel: prev.dateLabel, titre: r.titre, accroche: r.accroche, description: r.description, tags: r.tags || [], hypothese: r.hypothese || '',
  segments: segs, total_extraits_s: Math.round(total), publier_a: pub.toISOString(),
  voix_intro: r.voix_intro || '', voix_outro: r.voix_outro || '',
  requete: { nom, date_label: prev.dateLabel, accroche: r.accroche, miniature_texte: String(r.miniature_texte || '').slice(0, 60), decor_prompt: String(r.decor_prompt || '').slice(0, 500), vedette: Math.max(0, segs.findIndex(s => s.id_moment === r.vedette)), voix_intro: String(r.voix_intro || '').slice(0, 600), voix_outro: String(r.voix_outro || '').slice(0, 300), segments: segs.map(({ video_id, start, end, titre, contexte, source, voix }) => ({ video_id, start, end, titre, contexte, source, voix })) } } }];

const c = $('Conducteur').first().json;
const job = $('État du montage').last().json;
const mmss = t => `${String(Math.floor(t / 60)).padStart(2, '0')}:${String(Math.round(t % 60)).padStart(2, '0')}`;
const chap = ['00:00 Intro', ...(job.chapitres || []).map(ch => `${mmss(ch.t)} ${ch.titre}`)];
const sources = [...new Set(c.segments.map(s => s.source))];
const description = `${c.description}

Au sommaire :
${chap.join('
')}

Sources : ${sources.join(', ')}.${sources.some(s => /s[ée]nat/i.test(s)) ? '
Images fournies par le Sénat français.' : ''}${sources.some(s => /assembl[ée]e nationale/i.test(s)) ? '
Images : Assemblée nationale.' : ''}
Extraits courts cités à des fins d'information et de revue de l'actualité ; tous droits aux ayants droit.${(job.voix && job.voix.generees) ? '
Voix off générée par synthèse vocale.' : ''}

L'Extrait politique — le zapping quotidien de la politique française, chaque soir à 19h.
#politique #actualite #zapping`;
return [{ json: { ...c, description_finale: description, fichier: job.fichier, miniature: job.miniature, duree_s: job.duree_s, chapitres: job.chapitres || [], erreurs_montage: job.erreurs || [], miniature_erreurs: job.miniature_erreurs || [], originaux_longs: job.originaux_longs || [], voix: job.voix || {}, sources } }];

const c = $('Description').first().json;
let yt = {}; try { yt = $('Publier sur YouTube').first().json; } catch (e) {}
let fb = {}; try { fb = $('Publier sur Facebook').first().json; } catch (e) {}
let th = {}; try { th = $('Miniature YouTube').first().json; } catch (e) {}
const esc = s => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const m = Math.floor(c.duree_s / 60), s = c.duree_s % 60;
const lignes = [
  `🎬 <b>Zapping du ${esc(c.dateLabel)} publié</b>`, `<b>${esc(c.titre)}</b> · ${m} min ${s} s · ${c.chapitres.length} extraits`, '',
  ...c.chapitres.map((ch, i) => `${i + 1}. ${esc(ch.titre)} <i>(${esc(ch.source)})</i>`), '',
  yt.uploadId ? `✅ YouTube : https://youtu.be/${yt.uploadId}` : `❌ YouTube : ${esc((yt.error && (yt.error.message || yt.error)) || 'échec')}`,
  (c.originaux_longs || []).filter(x => x.includes('remplacé')).length ? `🔁 ${(c.originaux_longs || []).filter(x => x.includes('remplacé')).length} extrait(s) vertical(aux) remplacé(s) par la version longue 16:9` : '',
  (c.miniature_erreurs || []).length ? `🖼️ Miniature simplifiée : ${esc(String(c.miniature_erreurs[0]).slice(0, 150))}` : '',
  (yt.uploadId && th.error) ? `⚠️ Miniature non appliquée (vérifie la chaîne par téléphone dans YouTube Studio pour autoriser les miniatures)` : '',
  fb.id ? `✅ Facebook : https://www.facebook.com/${fb.id}` : `❌ Facebook : ${esc((fb.error && fb.error.message) || 'échec')}`,
  c.erreurs_montage.length ? `⚠️ ${c.erreurs_montage.length} extrait(s) n'ont pas pu être montés` : '',
  (c.voix && c.voix.demandees && !c.voix.generees) ? `🔇 Voix off absente : ${esc(((c.voix.erreurs || [])[0] || 'clé ElevenLabs manquante').includes('quota') ? 'crédit ElevenLabs épuisé, recharge ou passe au plan supérieur' : ((c.voix.erreurs || [])[0] || 'clé ElevenLabs manquante dans le serveur'))}` : '',
  (c.voix && c.voix.generees && (c.voix.erreurs || []).length) ? `⚠️ Voix off partielle (${c.voix.erreurs.length} passage(s) sans voix)` : '',
  '', `🧪 Hypothèse testée aujourd'hui : ${esc(c.hypothese)}`,
].filter(x => x !== '');
const ids = c.segments.map(x => x.video_id);
return [{ json: { texte: lignes.join('\n').slice(0, 4000), yt_id: yt.uploadId || '', fb_id: fb.id || '',
  pub_row: { data: [{ pub_id: c.nom, type: 'zapping', publiee_le: new Date().toISOString(), titre: c.titre, yt_id: yt.uploadId || '', fb_id: fb.id || '', ig_id: '',
    sources: JSON.stringify(c.sources), segments: JSON.stringify({ segments: c.chapitres.map(ch => { const s = c.segments.find(x => x.video_id === ch.video_id) || {}; return { ...ch, contexte: s.contexte, personnes: s.personnes, camp: s.camp, theme: s.theme, type_moment: s.type_moment }; }), hypothese: c.hypothese, accroche: c.accroche }),
    duree_s: c.duree_s, heure: '19:00', statut_yt: yt.uploadId ? 'public' : 'echec', alerte: '' }] },
  maj_videos: { filter: { type: 'or', filters: ids.map(v => ({ columnName: 'video_id', condition: 'eq', value: v })) }, data: { statut: 'zapping' } } } }];
